// Amigo secreto: quem você tirou reage depois (comprou presente durante o evento? então lembra com carinho)
const santaGot = ctx => { const a = Quests.act('amigo'); return !!(a && a.p && a.p.buy) || socEvDone('amigo', ctx); };
[['otavio', L3('Recebi um presente do amigo secreto. Desconfio que foi você. Obrigado. Não vou abrir na frente de ninguém.', 'Got a Secret Santa gift. I suspect it was you. Thank you. I won\'t open it in front of anyone.', 'Recibí un regalo del amigo invisible. Sospecho que fuiste tú. Gracias. No lo abriré frente a nadie.'), L3('Meu amigo secreto não me deu nada. Estatisticamente previsível.', 'My Secret Santa gave me nothing. Statistically predictable.', 'Mi amigo invisible no me dio nada. Estadísticamente previsible.')],
 ['duda', L3('GANHEI PRESENTE DO AMIGO SECRETO. foi você? tem cara de ter sido você. VALEU', 'I GOT A SECRET SANTA GIFT. was it you? it feels like you. THANKS', 'ME LLEGÓ EL REGALO DEL AMIGO INVISIBLE. ¿fuiste tú? tiene pinta. GRACIAS'), L3('meu amigo secreto esqueceu de mim. tudo bem. eu tenho o servidor', 'my secret santa forgot me. it\'s fine. I have the server', 'mi amigo invisible se olvidó de mí. está bien. tengo el servidor')],
 ['helena', L3('recebi um presente. papel de carta e um chá. aceitável. muito aceitável.', 'i received a gift. stationery and tea. acceptable. very acceptable.', 'recibí un regalo. papel de carta y un té. aceptable. muy aceptable.'), L3('meu amigo secreto não compareceu. anotado.', 'my secret santa did not show up. noted.', 'mi amigo invisible no se presentó. anotado.')],
 ['rafa', L3('ganhei presente!! nota 9. o 10 é só pra presente que eu mesmo compro', 'got a gift!! 9 out of 10. 10s are only for gifts I buy myself', '¡¡me dieron regalo!! un 9. el 10 es solo para regalos que me compro yo'), L3('meu amigo secreto me deu NADA. vou descobrir quem foi', 'my secret santa gave me NOTHING. I\'m finding out who', 'mi amigo invisible me dio NADA. voy a descubrir quién fue')],
].forEach(([npc, got, none]) => socThreads([{ id: npc + '_santa', npc, prio: 70, work: true, perCycle: true, when: { f: 'santa', evPast: 'amigo', known: npc }, end: { uf: 'santa' }, n: {
  a: { say: [], go: [{ if: { fn: ctx => santaGot(ctx) }, to: 'got' }, 'none'] }, got: { say: [got], fx: { aff: 2, f: 'gotGift' } }, none: { say: [none], fx: { aff: -1 } } } }]));

